// Apply only this plugin's source-copy mod after its manifest/package registration
// has already been generated by Expo prebuild. Does not rerun other native mods.
const fs = require('node:fs/promises');
const path = require('node:path');
const withLiveNotifications = require('./index');

(async () => {
  const projectRoot = path.resolve(__dirname, '../..');
  const config = JSON.parse(await fs.readFile(path.join(projectRoot, 'app.json'), 'utf8')).expo;
  const platformProjectRoot = path.join(projectRoot, 'android');
  const mainRoot = path.join(platformProjectRoot, 'app', 'src', 'main');
  const manifest = await fs.readFile(path.join(mainRoot, 'AndroidManifest.xml'), 'utf8');
  const application = await fs.readFile(path.join(mainRoot, 'java', ...config.android.package.split('.'), 'MainApplication.kt'), 'utf8');
  if (!manifest.includes('kz.birge.notifications.BirgeLiveNotificationsService') || !manifest.includes('android.permission.FOREGROUND_SERVICE_REMOTE_MESSAGING') || !application.includes('add(BirgeLiveNotificationsPackage())')) {
    throw new Error('Run Expo prebuild once to register Birge notifications before using the source-only plugin sync.');
  }
  const plugin = withLiveNotifications(config);
  await plugin.mods.android.dangerous({ ...plugin, modRequest: { platform:'android', projectRoot, platformProjectRoot } });
  console.log('Birge notification native sources synced by the Expo config plugin; other native configuration and C++ caches were untouched.');
})().catch(error => { console.error(error.message); process.exitCode = 1; });
